INSERT INTO changelog (title, body, created_at) VALUES
('Джері: на весь екран і меню «+»',
'Віконце Джері на компʼютері розгортається на весь екран — кнопка ⤢ біля хрестика (вибір запамʼятовується). Зліва в полі вводу — «+» з меню: прикріпити фото або файл (картинки, PDF, текст; або просто встав скрін Ctrl+V чи перетягни файл у поле), на телефоні — зробити фото камерою; тумблери «Пошук в інтернеті», «Бачить задачу і рекламу», «Читати відповіді вголос»; «Нова розмова». Прикріплені картинки і PDF Джері бачить сам (до 6 файлів, разом до ~20 МБ; великі фото стискаються). В історії розмови лишаються назви файлів, самі файли — тільки в тому повідомленні.',
'2026-11-01 21:00:00');
